import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { default as primitives } from '@/primitives';
import { default as text } from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Plane geometry – size chosen to fit a horizontal row (7 × 0.5 scene units)
  const geometry = new ctx.THREE.PlaneGeometry(7, 0.5);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    map: null,
  });

  const mesh = new ctx.THREE.Mesh(geometry, material);
  group.add(mesh);

  // Load texture asynchronously; material will be updated when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---------- Interaction: ----------
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(mesh.position, {
    y: '+=0.15',
    duration: 0.7,
    ease: 'power3.out',
  });

  function onHoverEnter() {
    hoverTimeline.play(0);
  }

  function onHoverLeave() {
    hoverTimeline.reverse();
  }

  function onClick() {
    ctx.emit('hub-collection.select', {});
  }

  // Attach handlers to userData as required by the runtime
  group.userData.handlers = {
    hover: { onEnter: onHoverEnter, onLeave: onHoverLeave },
    click: onClick,
  };

  // ---------- Cleanup ----------
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    geometry.dispose();
    material.dispose();
    // Primitive cleanup (none for this node, but keep pattern)
    // if (ctx.primitives) { /* no primitives to clean */ }
  };

  return group;
}
